async function recover(){if(!pending||busy)return;busy=true;render();try{const result=await api(pending.path,pending.method,pending.body);if(result.session_id)chosen=result.session_id;pending=null;sessionStorage.removeItem('ncw-pending');await load();const held=current()?.state==='BLOCKED';toast(held?'Saved: this session needs attention. Read the explanation below.':result.replayed?'Saved action recovered without duplication.':'Workflow action saved.');}catch(e){if(e.status&&e.status<500){pending=null;sessionStorage.removeItem('ncw-pending');}error=e.message;toast(e.message.replaceAll('_',' ')+(pending?' Retry will use the same operation ID.':''),true);}finally{busy=false;render();}}
